﻿<style>

/* ============ TOKENS (ubah warna/font di sini) ============ */
:root{
  /* Brand Kala: peach #FFBFA2 + putih hangat */
  --peach:#FFBFA2;
  --bg:#FFF8F4;
  --bg-soft:#FFE6DA;
  --surface:#FFFFFF;
  --ink:#4B2B1F;
  --ink-soft:#7B5647;
  --brand:#B8532F;
  --brand-dark:#8F3E22;
  --accent:#B8532F;
  --accent-dark:#9A4222;
  --sun:#FFE9B8;
  --line:#F5D5C6;

  --font-head:"Fredoka",system-ui,sans-serif;
  --font-body:"Nunito",system-ui,sans-serif;

  --r-sm:12px; --r-md:20px; --r-lg:32px;
  --shadow:0 10px 30px rgba(120,60,30,.10);
  --wrap:1120px;
}

/* ============ RESET ============ */
.kala-html-raw *,.kala-html-raw *::before,.kala-html-raw *::after{box-sizing:border-box}
html{scroll-behavior:smooth}
.kala-html-raw{margin:0;font-family:var(--font-body);font-size:17px;line-height:1.65;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
.kala-html-raw img{max-width:100%;display:block}
.kala-html-raw h1,.kala-html-raw h2,.kala-html-raw h3,.kala-html-raw h4{font-family:var(--font-head);line-height:1.2;margin:0 0 .5em;font-weight:600;color:var(--ink)}
.kala-html-raw p{margin:0 0 1em}
.kala-html-raw a{color:inherit}
.kala-html-raw :focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:6px}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.kala-html-raw *{transition:none!important}}

.kala-html-raw .wrap{max-width:var(--wrap);margin:0 auto;padding:0 20px}
.kala-html-raw section{padding:76px 0}
.kala-html-raw .center{text-align:center}
.kala-html-raw .lead{max-width:60ch;color:var(--ink-soft);font-size:1.05rem}
.kala-html-raw .center .lead{margin-inline:auto}
.kala-html-raw .kicker{display:inline-block;font-weight:800;font-size:.9rem;color:var(--brand);background:var(--bg-soft);padding:6px 14px;border-radius:99px;margin-bottom:16px}
.kala-html-raw h2{font-size:clamp(1.7rem,4vw,2.5rem)}

/* ============ BUTTONS ============ */
.kala-html-raw .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font:700 1rem var(--font-body);text-decoration:none;padding:15px 28px;border-radius:99px;border:2px solid transparent;cursor:pointer;transition:transform .15s,background .15s,box-shadow .15s}
.kala-html-raw .btn:hover{transform:translateY(-2px)}
.kala-html-raw .btn-primary{background:var(--accent);color:#fff;box-shadow:0 8px 20px rgba(242,139,130,.4)}
.kala-html-raw .btn-primary:hover{background:var(--accent-dark)}
.kala-html-raw .btn-ghost{border-color:var(--brand);color:var(--brand);background:transparent}
.kala-html-raw .btn-ghost:hover{background:var(--brand);color:#fff}
.kala-html-raw .btn-wa{background:var(--brand);color:#fff;box-shadow:0 8px 20px rgba(184,83,47,.35)}
.kala-html-raw .btn-wa:hover{background:var(--brand-dark)}
.kala-html-raw .btn-block{width:100%}

/* ============ HERO ============ */
.kala-html-raw .hero{position:relative;overflow:hidden;padding:56px 0 84px;background:var(--peach)}
.kala-html-raw .hero-logo{width:clamp(230px,52vw,400px);height:auto;margin:0 auto 20px}
.kala-html-raw .hero .wrap{max-width:860px;text-align:center}
.kala-html-raw .trust{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--line);padding:8px 18px;border-radius:99px;font-weight:700;font-size:.92rem;box-shadow:var(--shadow);margin-bottom:26px}
.kala-html-raw .hero h1{font-size:clamp(2.2rem,6.5vw,4rem);letter-spacing:-.01em;margin-bottom:.4em}
.kala-html-raw .hero h1 em{font-style:normal;color:var(--brand-dark)}
.kala-html-raw .hero .lead{font-size:1.15rem;margin:0 auto 32px;color:var(--ink)}
.kala-html-raw .hero .btn-ghost{border-color:var(--ink);color:var(--ink)}
.kala-html-raw .hero .btn-ghost:hover{background:var(--ink);color:#fff}
.kala-html-raw .cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}
.kala-html-raw .hero-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:56px}
.kala-html-raw .hero-stats div{background:var(--surface);border-radius:var(--r-md);padding:20px 10px;box-shadow:var(--shadow)}
.kala-html-raw .hero-stats strong{display:block;font:700 clamp(1.5rem,4vw,2.2rem) var(--font-head);color:var(--brand)}
.kala-html-raw .hero-stats span{font-size:.92rem;color:var(--ink-soft)}

/* ============ CONCERNS ============ */
.kala-html-raw .concerns{background:var(--surface)}
.kala-html-raw .grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:44px}
.kala-html-raw .card{background:var(--bg);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;display:flex;flex-direction:column}
.kala-html-raw .card .photo{aspect-ratio:4/3;background:var(--bg-soft);overflow:hidden}
.kala-html-raw .card .photo img{width:100%;height:100%;object-fit:cover}
.kala-html-raw .card .body{padding:24px;position:relative}
.kala-html-raw .card .emoji{font-size:1.8rem;display:block;margin-bottom:8px}
.kala-html-raw .card h3{font-size:1.25rem}
.kala-html-raw .card p{color:var(--ink-soft);margin:0}

/* ============ BENEFITS ============ */
.kala-html-raw .benefits-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:44px}
.kala-html-raw .benefit{display:flex;gap:18px;background:var(--surface);border-radius:var(--r-md);padding:24px;box-shadow:var(--shadow)}
.kala-html-raw .benefit .ico{flex:none;width:56px;height:56px;display:grid;place-items:center;font-size:1.6rem;background:var(--bg-soft);border-radius:16px}
.kala-html-raw .benefit h4{font-size:1.1rem;margin-bottom:.3em}
.kala-html-raw .benefit p{margin:0;color:var(--ink-soft);font-size:.97rem}

.kala-html-raw .quote{margin:44px auto 0;max-width:720px;background:var(--peach);color:var(--ink);border-radius:var(--r-lg);padding:36px 32px;text-align:center}
.kala-html-raw .quote blockquote{margin:0 0 12px;font:500 clamp(1.15rem,3vw,1.5rem)/1.4 var(--font-head)}
.kala-html-raw .quote cite{font-style:normal;opacity:.85;font-size:.95rem}

.kala-html-raw .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:44px;text-align:center}
.kala-html-raw .stats div{padding:20px 8px;border-top:4px solid var(--accent);background:var(--surface);border-radius:0 0 var(--r-md) var(--r-md);box-shadow:var(--shadow)}
.kala-html-raw .stats strong{display:block;font:700 2.2rem var(--font-head);color:var(--brand)}
.kala-html-raw .stats span{font-size:.92rem;color:var(--ink-soft)}

/* ============ PROMO ============ */
.kala-html-raw .promo{background:var(--bg-soft)}
.kala-html-raw .promo-box{max-width:760px;margin:0 auto;background:var(--surface);border-radius:var(--r-lg);padding:48px 32px;text-align:center;box-shadow:var(--shadow);position:relative;border:3px dashed var(--accent)}
.kala-html-raw .promo-box .label{color:var(--ink-soft);font-weight:700;margin-bottom:6px}
.kala-html-raw .price{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:12px 18px;margin:8px 0 14px}
.kala-html-raw .price .old{font:500 1.5rem var(--font-head);color:var(--ink-soft);text-decoration:line-through}
.kala-html-raw .price .new{font:700 clamp(2.6rem,8vw,3.8rem) var(--font-head);color:var(--accent-dark)}
.kala-html-raw .badge{display:inline-block;background:var(--sun);color:#7A4B00;font-weight:800;padding:5px 14px;border-radius:99px;font-size:.88rem;margin-bottom:26px}
.kala-html-raw .promo-box .fine{display:block;margin-top:18px;font-size:.88rem;color:var(--ink-soft)}

/* ============ SERVICES ============ */
.kala-html-raw .services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:44px}
.kala-html-raw .service{background:var(--surface);border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow);display:flex;flex-direction:column;position:relative}
.kala-html-raw .service .photo{aspect-ratio:4/3;background:var(--bg-soft)}
.kala-html-raw .service .photo img{width:100%;height:100%;object-fit:cover}
.kala-html-raw .service .body{padding:24px;display:flex;flex-direction:column;flex:1}
.kala-html-raw .service .ico{font-size:1.6rem}
.kala-html-raw .service h3{font-size:1.25rem;margin:4px 0 8px}
.kala-html-raw .service p{color:var(--ink-soft);font-size:.97rem;flex:1}
.kala-html-raw .service .meta{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:6px}
.kala-html-raw .duration{font-weight:800;font-size:.9rem;color:var(--brand);background:var(--bg-soft);padding:5px 12px;border-radius:99px}
.kala-html-raw .service .btn{padding:10px 20px;font-size:.92rem}
.kala-html-raw .pop{position:absolute;top:14px;left:14px;z-index:2;background:var(--accent);color:#fff;font-weight:800;font-size:.82rem;padding:6px 14px;border-radius:99px}

/* ============ STEPS ============ */
.kala-html-raw .steps{background:var(--surface)}
.kala-html-raw .steps-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:44px;counter-reset:s}
.kala-html-raw .step{position:relative;padding:28px 22px;background:var(--bg);border-radius:var(--r-md);border:1px solid var(--line)}
.kala-html-raw .step .num{width:44px;height:44px;border-radius:50%;background:var(--brand);color:#fff;display:grid;place-items:center;font:700 1.2rem var(--font-head);margin-bottom:14px}
.kala-html-raw .step h3{font-size:1.1rem}
.kala-html-raw .step p{margin:0;font-size:.95rem;color:var(--ink-soft)}

/* ============ TESTIMONIALS ============ */
.kala-html-raw .testi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:44px}
.kala-html-raw .testi{background:var(--surface);border-radius:var(--r-lg);padding:28px;box-shadow:var(--shadow);display:flex;flex-direction:column}
.kala-html-raw .stars{color:#F5B301;letter-spacing:3px;margin-bottom:12px}
.kala-html-raw .testi p{flex:1;font-size:.98rem}
.kala-html-raw .who{display:flex;align-items:center;gap:12px;margin-top:8px}
.kala-html-raw .who .av{width:46px;height:46px;border-radius:50%;background:var(--bg-soft);display:grid;place-items:center;font-size:1.4rem}
.kala-html-raw .who strong{display:block;font-family:var(--font-head)}
.kala-html-raw .who span{font-size:.85rem;color:var(--ink-soft)}

/* ============ GUARANTEE ============ */
.kala-html-raw .guarantee{background:var(--sun)}
.kala-html-raw .guarantee .wrap{max-width:760px;text-align:center}
.kala-html-raw .guarantee .shield{font-size:3rem;display:block;margin-bottom:6px}
.kala-html-raw .guarantee p{color:#5E4A1B}

/* ============ FINAL CTA ============ */
.kala-html-raw .final{background:var(--peach);color:var(--ink);text-align:center}
.kala-html-raw .final h2{color:var(--ink)}
.kala-html-raw .final .lead{color:var(--ink);margin-inline:auto}
.kala-html-raw .final .note{display:block;margin-top:18px;font-size:.92rem;color:var(--ink)}

.kala-html-raw footer{padding:26px 0 90px;text-align:center;font-size:.88rem;color:var(--ink-soft)}

/* ============ FLOATING WA ============ */
.kala-html-raw .float-wa{position:fixed;right:16px;bottom:16px;z-index:60;box-shadow:0 10px 28px rgba(0,0,0,.25)}

/* ============ RESPONSIVE ============ */
@media (max-width:960px){
  .kala-html-raw .grid-3,.kala-html-raw .services-grid,.kala-html-raw .testi-grid{grid-template-columns:repeat(2,1fr)}
  .kala-html-raw .steps-grid{grid-template-columns:repeat(2,1fr)}
  .kala-html-raw .stats{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:640px){
  .kala-html-raw{font-size:16px}
  .kala-html-raw section{padding:56px 0}
  .kala-html-raw .grid-3,.kala-html-raw .services-grid,.kala-html-raw .testi-grid,.kala-html-raw .steps-grid,.kala-html-raw .benefits-grid{grid-template-columns:1fr}
  .kala-html-raw .hero{padding:48px 0 60px}
  .kala-html-raw .hero-stats{gap:10px}
  .kala-html-raw .hero-stats div{padding:14px 6px}
  .kala-html-raw .promo-box{padding:36px 20px}
  .kala-html-raw .cta-row .btn{width:100%}
}

/* [patch-2026-11-20] CTA mobile guard */
@media (max-width:767px){.kala-html-raw .float-wa{display:none!important}}
.kala-html-raw #booking,.kala-html-raw #layanan{scroll-margin-top:96px}

</style>
